{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Elbasvir, the closest analogue sharing the bis-imidazole-pyrrolidine carbamate scaffold, has an absolute oral bioavailability of approximately 32% in HCV-infected subjects, directly supporting F ≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Ledipasvir, another NS5A inhibitor with the same carbamate-pyrrolidine-imidazole pharmacophore, has an estimated oral bioavailability of about 53% in humans, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest structural analogues, elbasvir and ledipasvir, both have experimental oral bioavailability values above the 20% threshold (32% and 53%, respectively). Although the query differs in its central core and the fasted condition is not explicitly matched, the shared pharmacophore and consistent high-F evidence among related NS5A inhibitors support a high bioavailability prediction.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the exact query molecule.",
    "Fasted-state conditions are specified for the query but not consistently reported for the closest analogues; food effects could modulate F.",
    "The query's central biphenyl core differs from elbasvir's fused core and ledipasvir's fluorene core, so the exact F may differ from these analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

